import java.util.*;class BankAccount implements Comparable<BankAccount>{String id;long balance;BankAccount(String i,long b){id=i;balance=b;}public int compareTo(BankAccount a){return id.compareTo(a.id);}public String toString(){return id+"="+balance;}}class AccountStore{Map<String,BankAccount> map=new HashMap<>();List<String>history=new ArrayList<>();void add(BankAccount a){map.put(a.id,a);history.add("Added "+a.id);}BankAccount get(String id){return map.get(id);}List<BankAccount> sortedByBalance(){List<BankAccount>a=new ArrayList<>(map.values());a.sort(Comparator.comparingLong((BankAccount q)->q.balance).reversed());return a;}}public class AccountStoreDemo{public static void main(String[]x){AccountStore s=new AccountStore();s.add(new BankAccount("AC1",5000));s.add(new BankAccount("AC2",2000));s.add(new BankAccount("AC3",9000));System.out.println(s.get("AC2"));System.out.println(s.sortedByBalance());}}
